INSERT OR IGNORE INTO research_projects (id, product_name, country, platform, language, status, status_label, progress, detail, mode_label, codex_thread_id, asset_count, result_json, updated_at) VALUES ('research-1787110570986-10f7ecb1', '透明硬质收纳箱', '美国', 'TikTok Shop', '国语', 'completed', '商品调研完成', 100, '完整方案已同步回工作台，等待审核后进入脚本与分镜。', '商品调研', '01a01817-ac84-7310-8fc8-d510b99b6e03', 2, '{"jobType":"product_research","title":"透明硬质收纳箱｜美国 TikTok Shop 商品调研","scope":{"country":"美国","platform":"TikTok Shop","language":"国语","researchBoundary":"仅依据 task.json 与两张用户上传的产品资料进行判断；未使用实时市场、竞品、销量、价格或认证数据。资料中的日文功能说明、尺寸标注和系列展示视为图片证据。"},"productUnderstanding":[{"fact":"商品为透明硬质收纳箱，配有箱盖。","evidence":"task.json 的 productName 为“透明硬质收纳箱”；两张资料图均展示透明箱体与独立箱盖。","status":"可证实事实"},{"fact":"主展示款外部标注尺寸为长53cm、宽39cm、高32cm。","evidence":"asset-01-2.png 的产品尺寸箭头分别标注53cm、39cm、32cm。","status":"可证实事实"},{"fact":"箱盖采用外扣式锁扣结构。","evidence":"asset-01-2.png 的日文功能说明指出箱体带锁扣，采用アップロック式；图片可见黑色外部锁扣。","status":"可证实事实"},{"fact":"箱盖两侧设有可供绑带通过或定位的沟槽。","evidence":"asset-01-2.png 第③项标注“バンドがかけられる溝付き”，并用黄色绑带示意固定方式。","status":"可证实事实"},{"fact":"箱体两侧具有搬运时可握持的结构。","evidence":"asset-01-2.png 第④项说明两侧具有便于手持搬运的把手，并配有手提示意图。","status":"可证实事实"},{"fact":"资料展示了箱体堆叠使用场景。","evidence":"asset-01-2.png 第②项展示多只收纳箱上下堆叠，并说明可进行较高位置的堆放。","status":"可证实事实"},{"fact":"产品可安装另售脚轮，资料称最多可安装4个，安装后约增加7cm高度。","evidence":"asset-01-2.png 第⑤项明确标注キャスター为别售、最多安装4个以及约7cm高度变化。","status":"可证实事实"},{"fact":"该系列至少展示17个型号，按深度约21–35、39–44、53、66、74进行分组。","evidence":"asset-02-3.png 展示200S、300S、300M、390M、440S、440M、440L、530S、530M、530L、660S、660M、660L、660-2L、740M、740L、740-2L、740-3L，并以日文“奥行”分组。","status":"可证实事实"},{"fact":"透明箱体可能有助于用户在不开箱的情况下识别内部物品。","evidence":"两张资料图中箱体均为透明或半透明，可直接看到内部轮廓；资料未提供透光率或清晰度参数。","status":"合理推断"},{"fact":"该产品可能适合衣物、换季用品和家庭杂物整理。","evidence":"asset-01-2.png 第④项出现衣物收纳示意，并提及衣替え；其他具体用途未被逐项验证。","status":"合理推断"},{"fact":"箱体材质、容量、净重、承重、耐温、防水防尘等级、食品接触安全性及具体生产信息均无法确认。","evidence":"task.json 与两张资料图未提供这些参数。","status":"缺失信息"},{"fact":"主展示款对应的具体型号无法仅凭现有资料可靠确认。","evidence":"asset-01-2.png 显示53×39×32cm，asset-02-3.png 展示多个深度53系列型号，但没有提供完整型号尺寸对照。","status":"缺失信息"}],"audiences":[{"segment":"租房者与小户型家庭","profile":"储物空间有限，希望利用床下、衣柜、储藏间或纵向空间的人群。","scenario":"换季整理、搬家前打包、日常杂物分类。","motivation":"提升有限空间的整洁度，并能快速识别箱内物品。","priority":"高"},{"segment":"有家庭集中收纳需求的用户","profile":"需要整理衣物、儿童用品、节庆用品或家庭杂物的家庭用户。","scenario":"衣柜、车库、地下室或储藏室集中整理。","motivation":"统一容器、分类堆放，减少寻找和重复翻箱。","priority":"高"},{"segment":"频繁搬家或宿舍迁移人群","profile":"学生、年轻职场人及租约变动较频繁的用户。","scenario":"装箱、绑带加固、手提搬运和到达后的继续收纳。","motivation":"希望同一容器兼顾打包、移动与长期收纳。","priority":"中"},{"segment":"重视可视化管理的整理爱好者","profile":"习惯按类别整理，希望快速查看库存的人群。","scenario":"衣物、手工材料、玩具或非敏感杂物分类。","motivation":"通过透明箱体减少标签依赖和开箱确认次数。","priority":"中"},{"segment":"行动不便或不愿频繁搬抬重箱的用户","profile":"希望通过脚轮降低移动负担的人群。","scenario":"在平整室内地面移动收纳箱。","motivation":"改善装满物品后移动困难的问题。","priority":"低；脚轮兼容性及承载能力尚未确认"}],"painPoints":[{"painPoint":"收纳后看不见内容物，寻找物品时需要反复开箱。","audience":"家庭用户、整理爱好者","currentAlternative":"不透明箱配标签、纸箱或开放式收纳。","productResponse":"透明箱体提供可视化识别能力。","contentProof":"拍摄多只箱子中快速找到目标衣物的对比演示，但不得宣称完全透明或无需标签。"},{"painPoint":"箱盖在搬动或装箱过程中可能松脱。","audience":"租房者、学生、搬家人群","currentAlternative":"胶带封箱、绳子捆扎或普通无扣箱。","productResponse":"外扣式锁扣固定箱盖；盖侧沟槽可辅助绑带定位。","contentProof":"近景展示锁扣开合，并在合规负载下演示绑带经过沟槽；避免跌落和极限拉扯测试。"},{"painPoint":"小空间难以充分利用纵向储物位置。","audience":"小户型家庭、租房者","currentAlternative":"散放、纸箱堆放或购买固定柜体。","productResponse":"资料展示了箱体堆叠使用方式。","contentProof":"拍摄整理前后占地变化与低层堆叠场景；在承重数据缺失时不得宣传可无限或超高堆叠。"},{"painPoint":"装满后的箱子不易搬运。","audience":"家庭用户、搬家人群","currentAlternative":"抱住箱体、使用搬家袋或临时推车。","productResponse":"两侧握持结构便于手提；资料还展示可安装另售脚轮。","contentProof":"展示空箱或轻载手提动作，并明确脚轮另售；未验证重量前不做重载演示。"},{"painPoint":"不同空间深度和物品体积难以匹配单一尺寸。","audience":"多房间家庭、系统化整理用户","currentAlternative":"混用不同品牌容器或勉强使用不合适尺寸。","productResponse":"资料展示多个深度分组及多种型号。","contentProof":"制作“先量空间、再选型号”的尺寸选择内容；销售页只能呈现实际在售型号及完整尺寸。"}],"marketStrategy":{"positioning":"面向美国家庭与租房人群的可视化、可堆叠、便于搬运的硬质收纳解决方案；核心价值是“看得见、扣得住、按空间选尺寸”。","coreMessage":"不用反复开箱找东西：透明箱体让内容更直观，外扣锁盖帮助保持箱盖就位，多尺寸思路适配不同收纳空间。","entryAngle":"优先从“整理前后反差＋快速找到物品”切入，再用锁扣、绑带沟槽、握持结构和尺寸测量补充理性证据。","offerLogic":"以实际在售尺寸建立清晰变体选择；若商家确有多件装或脚轮选项，可设置组合购买，但在价格、库存和兼容性未确认前不预设折扣、赠品或脚轮包含关系。","conversionPath":"短视频前3秒展示杂乱与找不到物品的痛点→透明收纳后的视觉反差→锁扣、尺寸和搬运结构特写→提示先测量目标空间→进入 TikTok Shop 商品页查看实际尺寸与包装内容→选择变体→加购结算→用置顶评论和FAQ降低尺寸误选及脚轮误解。"},"platformPlaybook":[{"stage":"认知","objective":"用直观问题获得停留。","action":"发布整理前后、找物计时和小空间收纳短视频，首屏直接显示杂乱场景或“别再逐箱翻找”。","asset":"9:16实拍、透明箱体装物效果、前后对比字幕。","metric":"3秒留存率、平均观看时长、完播率。"},{"stage":"兴趣","objective":"证明结构价值并回答常见疑问。","action":"用特写依次展示透明箱体、锁扣、绑带沟槽、侧面握持位置及实际尺寸测量。","asset":"功能近景、卷尺测量、轻载开合演示。","metric":"商品点击率、评论提问量、收藏率。"},{"stage":"考虑","objective":"降低尺寸和变体选择阻力。","action":"在商品页、视频字幕和置顶评论中统一标注英制与公制尺寸、内外尺寸区别、包装数量及脚轮是否包含。","asset":"尺寸对照图、空间测量指南、变体命名表。","metric":"商品页停留、变体选择率、因尺寸产生的客服咨询率。"},{"stage":"转化","objective":"让用户基于明确用途完成购买。","action":"用卧室衣柜、宿舍、储藏室等单一场景视频对应具体在售型号，并使用商品锚点。","asset":"场景化短视频、商品卡、FAQ。","metric":"加购率、支付转化率、每千次观看成交量。"},{"stage":"复购与口碑","objective":"形成真实使用证据。","action":"引导买家展示实际摆放位置和整理结果，收集关于尺寸、锁扣与搬运体验的真实反馈。","asset":"买家内容授权素材、评论答疑视频。","metric":"评价率、用户生成内容数量、复购率、退货原因分布。"}],"contentDirections":[{"direction":"找物效率对比","hook":"“还在一箱一箱翻？透明收纳先让你看见。”","proof":"同类物品分别放入不透明容器与本产品，演示识别过程；只展示可观察结果。","cta":"先量好收纳位置，再到商品页选择实际在售尺寸。MISSING:具体尺寸变体需核实。","format":"短视频"},{"direction":"锁扣细节演示","hook":"“搬箱时最怕的，是箱盖突然松开。”","proof":"近景展示外扣式锁扣的开启和闭合状态，并展示盖侧绑带沟槽。","cta":"查看商品页确认包装内容和使用说明。","format":"短视频"},{"direction":"小空间整理前后","hook":"“地上越堆越乱？试试把收纳改成纵向规划。”","proof":"展示低层、稳定的堆叠整理效果，并保持箱体负载合理。","cta":"按可用宽度、高度和深度选择箱型。","format":"短视频"},{"direction":"搬家与宿舍收纳","hook":"“搬家箱用完就丢？这个思路可以继续当日常收纳。”","proof":"演示装入衣物、锁盖、通过沟槽加绑带和轻载搬运。","cta":"购买前确认外尺寸、容量和可承载重量。MISSING:容量与承重尚无资料。","format":"短视频"},{"direction":"尺寸避坑指南","hook":"“别只看容量，买箱子前先量这三个位置。”","proof":"用卷尺演示长、宽、高以及柜门、床底或搁架的净空间测量。","cta":"对照商品页的完整尺寸表选择型号。MISSING:在售型号完整尺寸表待补。","format":"短视频"},{"direction":"脚轮选配说明","hook":"“想推着走？先确认脚轮是不是包含在包装里。”","proof":"引用资料中脚轮另售、最多4个和约增高7cm的信息，同时展示安装位置；发布前核实美国在售配件。","cta":"在商品页确认兼容型号和配件是否另购。","format":"短视频"}],"risks":[{"risk":"把主展示款误认成某个530系列具体型号。","reason":"现有图片只显示53×39×32cm及独立的系列示意，没有完整型号尺寸映射。","guardrail":"未取得SKU表前使用“主展示款”表述，不绑定530S、530M或530L。"},{"risk":"过度宣传承重、耐压或超高堆叠能力。","reason":"资料只展示堆叠场景，没有提供静态承重、层数或测试标准。","guardrail":"仅展示低层稳定堆叠；不得使用“重载”“不会倒”“无限叠放”等承诺。"},{"risk":"消费者误以为脚轮随箱附送。","reason":"日文资料明确脚轮为另售配件。","guardrail":"商品页和视频醒目标注“脚轮另售/是否可购待确认”，并核实美国SKU兼容性。"},{"risk":"尺寸或容量误导造成退货。","reason":"目前仅有主展示款外部三维标注和系列深度分组，缺少完整内尺寸及容量。","guardrail":"核实每个在售SKU的外尺寸、内尺寸和容量；英寸换算后复核，并说明测量口径。"},{"risk":"将锁扣描述成密封、防水、防尘或防虫结构。","reason":"图片只能证明锁扣固定箱盖，不能证明密封性能。","guardrail":"使用“帮助固定箱盖”表述，不做未经测试的防护等级宣传。"},{"risk":"搬运演示引发安全或耐用性误解。","reason":"产品净重、装载上限、把手承载及跌落测试均未知。","guardrail":"采用空箱或轻载演示，不站人、不坐压、不跌落、不进行极限拉扯。"},{"risk":"日文资料与美国实际销售版本不一致。","reason":"上传资料为日文，配件、型号、包装和说明可能对应其他市场版本。","guardrail":"美国上架前以实际库存、英文包装、供应商规格书和实物复核为准。"},{"risk":"TikTok Shop 合规表达风险。","reason":"销量第一、最强、永久耐用等绝对化描述没有证据。","guardrail":"所有卖点使用可观察、可演示的事实；不虚构销量、认证、环保属性或性能测试。"}],"actionPlan":[{"priority":"P0","action":"建立美国实际在售SKU真值表，逐项核对型号、外尺寸、内尺寸、容量、净重、包装数量、颜色和条码。","owner":"商品运营＋供应链","deliverable":"经实物或供应商规格书确认的SKU参数表。"},{"priority":"P0","action":"确认材质、承重、堆叠限制、使用温度、锁扣寿命及是否具备任何防护或安全认证。","owner":"供应链＋合规负责人","deliverable":"可追溯的测试报告、规格书或“不可宣称”清单。"},{"priority":"P0","action":"核实美国版本是否支持脚轮、兼容脚轮型号、是否另售、包装是否包含及安装后的准确增高。","owner":"商品运营","deliverable":"美国SKU配件兼容表与商品页披露文案。"},{"priority":"P1","action":"为 TikTok Shop 制作统一的公制/英制尺寸图，并标明外尺寸、内尺寸和测量方式。","owner":"设计＋商品运营","deliverable":"变体尺寸对照图和“先量空间”购买指南。"},{"priority":"P1","action":"实拍验证锁扣开合、轻载搬运、绑带沟槽和低层堆叠，保留拍摄负载及条件记录。","owner":"内容团队＋质检","deliverable":"可用于短视频和商品页的证据素材库。"},{"priority":"P1","action":"完成美国 TikTok Shop 商品页本地化，明确实际包装内容、脚轮状态、使用限制和退换货相关尺寸提示。","owner":"电商运营＋合规负责人","deliverable":"英文商品页及国语内部审核稿。"},{"priority":"P2","action":"首轮测试三类内容：找物对比、尺寸避坑、锁扣细节，并保持同一商品锚点和清晰变量。","owner":"短视频运营","deliverable":"首轮测试视频及3秒留存、点击率、加购率和转化率记录。"},{"priority":"P2","action":"根据评论与退货原因补充FAQ，重点追踪尺寸误选、透明度预期、锁扣使用和脚轮误解。","owner":"客服＋商品运营","deliverable":"每周问题清单、FAQ更新和退货原因复盘。"}],"uncertainties":["美国 TikTok Shop 实际销售的具体型号、变体数量、库存和包装数量未知。","主展示款的准确型号未知；53×39×32cm是否均为外尺寸仍需供应商确认。","各型号的完整长、宽、高、内部可用尺寸、容量和净重未知。","产品具体材质、厚度、透明度、气味表现、回收属性和食品接触适用性未知。","箱体、箱盖、锁扣及侧面握持结构的承重、耐冲击、耐温和寿命测试未知。","允许堆叠的最大层数、负载条件及防倾倒要求未知。","锁扣是否具备密封、防水、防尘、防虫能力未知。","美国销售版本的脚轮是否可购买、与哪些型号兼容及实际价格未知。","美国版本的生产商、品牌授权、质保、合规文件和认证状态未知。","实际售价、促销空间、履约成本、运费、退货率和利润结构未知。","TikTok Shop 上同类商品的实时销量、价格、评价、内容热度、竞品表现和市场规模均无实时证据。","目标人群排序与内容方向目前基于产品功能和场景推断，尚未由美国站点搜索、广告或成交数据验证。"],"reviewGate":"进入短视频脚本或上架制作前，必须通过P0资料审核：SKU与尺寸对应准确、包装内容明确、脚轮状态明确、所有性能宣称具备证据。任何未通过项只能标为未知，不得转化为广告卖点。"}', '2026-08-19T03:40:27+08:00');
